{{
  (() => {
    const dane = Array.isArray(TableNabory.filteredTableData)
      ? TableNabory.filteredTableData
      : (Array.isArray(TableNabory.tableData)
          ? TableNabory.tableData
          : []);

    const statusy = [
      "planowany",
      "ogłoszony",
      "ocena formalna",
      "ocena merytoryczna",
      "procedowana uchwała",
      "zakończony",
      "anulowany",
      "unieważniony"
    ];

    const liczby = statusy.map(status =>
      dane.filter(r =>
        String(r.status ?? "").toLowerCase().trim() === status
      ).length
    );

    return `Liczba wszystkich naborów: ${dane.length}   |   ` +
      statusy.map((status, i) =>
        `${status.charAt(0).toUpperCase() + status.slice(1)}: ${liczby[i]}`
      ).join("   |   ");
  })()
}}
